// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {Scene} from "./Scene.sol";

/// @notice Entire two-second media files generated inside one pure EVM call.
/// @dev No stored frames, external assets, JavaScript, or offchain encoding.
///      Experimental encoders: literal GIF LZW and indexed, uncompressed AVI.
contract SolVideo is Scene {
    function _check(uint256 size, uint256 fps, uint256 scene) private pure {
        if (
            (size != 32 && size != 64 && size != 128 && size != 256) || (fps != 10 && fps != 20 && fps != 25)
                || scene > 10
        ) revert InvalidSettings();
    }

    /// @notice Looping GIF89a, exactly 2 seconds, with 20, 40 or 50 frames.
    function gif(uint256 size, uint256 fps, uint256 scene, uint256 seed) public pure returns (bytes memory out) {
        _check(size, fps, scene);
        uint256 frames = 2 * fps;
        uint256 n = size * size;
        uint256 packedSize = ((n + (n + 13) / 14 + 1) * 5 + 7) / 8;
        uint256 frameSize = 20 + packedSize + (packedSize + 254) / 255;
        out = new bytes(81 + frames * frameSize);
        _copy(out, 0, bytes("GIF89a"));
        _le(out, 6, size, 2);
        _le(out, 8, size, 2);
        out[10] = 0xf3; // global 16-entry palette, 8-bit colour resolution
        _copy(out, 13, _palette(scene, seed));
        _copy(out, 61, hex"21ff0b4e45545343415045322e300301000000");
        bytes memory pixels = new bytes(n);
        bytes memory background = _background(size, scene, seed);
        bytes memory packedPixels = new bytes(packedSize);
        uint256 p = 80;
        for (uint256 f; f < frames; ++f) {
            _draw(pixels, size, f, frames, scene, seed, background);
            _lzw(pixels, packedPixels);
            _copy(out, p, hex"21f90404000000002c00000000000000000004");
            _le(out, p + 4, 100 / fps, 2);
            _le(out, p + 13, size, 2);
            _le(out, p + 15, size, 2);
            p += 19;
            for (uint256 i; i < packedSize;) {
                uint256 count = packedSize - i;
                if (count > 255) count = 255;
                out[p++] = bytes1(uint8(count));
                assembly ("memory-safe") {
                    mcopy(add(add(out, 32), p), add(add(packedPixels, 32), i), count)
                }
                p += count;
                i += count;
            }
            out[p++] = 0; // image data terminator
        }
        assert(p == out.length - 1);
        out[p] = 0x3b;
    }

    /// @notice Actual RIFF AVI video: 8-bit indexed DIB, fixed 2 seconds, no audio.
    /// @dev Widths are multiples of 4, satisfying DIB scanline alignment.
    function avi(uint256 size, uint256 fps, uint256 scene, uint256 seed) public pure returns (bytes memory out) {
        _check(size, fps, scene);
        uint256 frames = fps * 2;
        uint256 n = size * size;
        uint256 movieSize = frames * (8 + n);
        out = new bytes(296 + movieSize + 16 * frames);
        _copy(out, 0, bytes("RIFF"));
        _le(out, 4, out.length - 8, 4);
        _copy(out, 8, bytes("AVI LIST"));
        _le(out, 16, 256, 4);
        _copy(out, 20, bytes("hdrlavih"));
        _le(out, 28, 56, 4);
        _le(out, 32, 1_000_000 / fps, 4);
        _le(out, 36, (n + 8) * fps, 4);
        _le(out, 44, 16, 4); // AVIF_HASINDEX
        _le(out, 48, frames, 4);
        _le(out, 56, 1, 4); // one stream
        _le(out, 60, n, 4);
        _le(out, 64, size, 4);
        _le(out, 68, size, 4);
        _copy(out, 88, bytes("LIST"));
        _le(out, 92, 180, 4);
        _copy(out, 96, bytes("strlstrh"));
        _le(out, 104, 56, 4);
        _copy(out, 108, bytes("vidsDIB "));
        _le(out, 128, 1, 4); // scale
        _le(out, 132, fps, 4); // rate
        _le(out, 140, frames, 4);
        _le(out, 144, n, 4);
        _le(out, 148, 0xffffffff, 4); // default quality
        _le(out, 160, size, 2);
        _le(out, 162, size, 2);
        _copy(out, 164, bytes("strf"));
        _le(out, 168, 104, 4); // BITMAPINFOHEADER + 16 RGBQUADs
        _le(out, 172, 40, 4);
        _le(out, 176, size, 4);
        _le(out, 180, size, 4);
        _le(out, 184, 1, 2); // planes
        _le(out, 186, 8, 2); // bits per pixel; BI_RGB = 0
        _le(out, 192, n, 4);
        _le(out, 204, 16, 4);
        _le(out, 208, 16, 4);
        bytes memory palette = _palette(scene, seed);
        for (uint256 i; i < 16; ++i) {
            out[212 + 4 * i] = palette[3 * i + 2];
            out[213 + 4 * i] = palette[3 * i + 1];
            out[214 + 4 * i] = palette[3 * i];
        }
        _copy(out, 276, bytes("LIST"));
        _le(out, 280, 4 + movieSize, 4);
        _copy(out, 284, bytes("movi"));
        bytes memory pixels = new bytes(n);
        bytes memory background = _background(size, scene, seed);
        uint256 p = 288;
        for (uint256 f; f < frames; ++f) {
            _draw(pixels, size, f, frames, scene, seed, background);
            _copy(out, p, bytes("00db"));
            _le(out, p + 4, n, 4);
            p += 8;
            // DIB scanlines are bottom-up; GIF scanlines are top-down.
            assembly ("memory-safe") {
                for { let y := 0 } lt(y, size) { y := add(y, 1) } {
                    mcopy(
                        add(add(out, 32), add(p, mul(y, size))),
                        add(add(pixels, 32), mul(sub(sub(size, 1), y), size)),
                        size
                    )
                }
            }
            p += n;
        }
        _copy(out, p, bytes("idx1"));
        _le(out, p + 4, 16 * frames, 4);
        p += 8;
        for (uint256 f; f < frames; ++f) {
            _copy(out, p, bytes("00db"));
            _le(out, p + 4, 16, 4); // every frame is a keyframe
            _le(out, p + 8, 4 + f * (8 + n), 4);
            _le(out, p + 12, n, 4);
            p += 16;
        }
        assert(p == out.length);
    }

    /// @dev Clear the dictionary every 14 literals: all codes stay 5 bits.
    /// This deliberately trades compression for simple, bounded EVM work.
    function _lzw(bytes memory pixels, bytes memory packedPixels) private pure {
        assembly ("memory-safe") {
            function emitCode(dst, bitPos, code) -> next {
                let p := add(dst, shr(3, bitPos))
                let offset := and(bitPos, 7)
                let v := shl(offset, code)
                // At a byte boundary, replace the previous frame's scratch byte.
                let old := 0
                if offset { old := byte(0, mload(p)) }
                mstore8(p, or(old, and(v, 255)))
                // A fresh following byte also clears any stale bits.
                mstore8(add(p, 1), shr(8, v))
                next := add(bitPos, 5)
            }
            let dst := add(packedPixels, 32)
            let src := add(pixels, 32)
            let n := mload(pixels)
            let bitPos := 0
            for { let i := 0 } lt(i, n) {} {
                bitPos := emitCode(dst, bitPos, 16)
                let end := add(i, 14)
                if gt(end, n) { end := n }
                for {} lt(i, end) { i := add(i, 1) } { bitPos := emitCode(dst, bitPos, byte(0, mload(add(src, i)))) }
            }
            pop(emitCode(dst, bitPos, 17))
        }
    }

    function _le(bytes memory out, uint256 p, uint256 value, uint256 count) private pure {
        for (uint256 i; i < count; ++i) {
            out[p + i] = bytes1(uint8(value >> (8 * i)));
        }
    }

    function _copy(bytes memory out, uint256 p, bytes memory value) private pure {
        assembly ("memory-safe") {
            mcopy(add(add(out, 32), p), add(value, 32), mload(value))
        }
    }
}

src/SolVideoNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {ERC721, Base64, Strings} from "../vendor/openzeppelin/Flattened.sol";
import {GenerativeVideo} from "./GenerativeVideo.sol";

/// @notice Limited-edition, zero-price ERC-721 whose artwork is an animated GIF rendered entirely onchain.
/// @dev One mint per caller address. No owner, upgrade, pause, fees, or privileged mint path.
contract SolVideoNFT is ERC721 {
    using Strings for uint256;

    error InvalidRenderer();
    error SoldOut();
    error AlreadyMinted();

    /// @dev The image is a small SVG around the base64 GIF. It asks for nearest-neighbour scaling at 16x, so viewers
    /// that upscale the 64px GIF keep hard pixel edges instead of smoothing it. Spaces and angle brackets are
    /// percent-encoded (RFC 2397), so the GIF is base64-encoded only once and the URI needs no other escaping.
    string private constant SVG_HEAD =
        "data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2064%2064'%20width='1024'%20height='1024'%3E%3Cimage%20width='64'%20height='64'%20image-rendering='optimizeSpeed'%20style='image-rendering:crisp-edges;image-rendering:pixelated'%20href='data:image/gif;base64,";
    string private constant SVG_TAIL = "'/%3E%3C/svg%3E";
    uint256 public constant MAX_SUPPLY = 6667;
    string public constant COLLECTION_NAME = "ghoulballs";
    string public constant COLLECTION_SYMBOL = "ghoulballs";
    GenerativeVideo public immutable renderer;
    uint256 public totalSupply;
    mapping(address => bool) public hasMinted;

    constructor(GenerativeVideo renderer_) ERC721(COLLECTION_NAME, COLLECTION_SYMBOL) {
        if (address(renderer_).code.length == 0) revert InvalidRenderer();
        renderer = renderer_;
    }

    /// @notice Mint one token for no payment; callers still pay network gas.
    function mint() external returns (uint256 tokenId) {
        return _mintNext(msg.sender);
    }

    /// @notice Gift one token. It uses the caller's single mint. Contract recipients must implement IERC721Receiver.
    function mintTo(address recipient) external returns (uint256 tokenId) {
        return _mintNext(recipient);
    }

    function _mintNext(address recipient) private returns (uint256 tokenId) {
        if (totalSupply >= MAX_SUPPLY) revert SoldOut();
        if (hasMinted[msg.sender]) revert AlreadyMinted();
        hasMinted[msg.sender] = true;
        tokenId = ++totalSupply;
        // The counter advances before the receiver hook, including reentrant mints.
        _safeMint(recipient, tokenId);
    }

    /// @notice Stable across time, owners and transfers. Distinct deployments use distinct seeds.
    function seedOf(uint256 tokenId) public view returns (uint256) {
        ownerOf(tokenId);
        return uint256(keccak256(abi.encode("SOL_VIDEO_NFT_V1", block.chainid, address(this), tokenId)));
    }

    function recipeOf(uint256 tokenId) external view returns (GenerativeVideo.Recipe memory) {
        return renderer.recipe(seedOf(tokenId));
    }

    /// @notice The token's raw GIF: 64x64, 20 frames at 10fps, a two-second loop.
    function gif(uint256 tokenId) external view returns (bytes memory) {
        return renderer.gifFromSeed(64, 10, seedOf(tokenId));
    }

    /// @notice Pixel-sharp SVG around the token's GIF.
    function imageURI(uint256 tokenId) public view returns (string memory) {
        return string.concat(SVG_HEAD, Base64.encode(renderer.gifFromSeed(64, 10, seedOf(tokenId))), SVG_TAIL);
    }

    /// @notice The GIF and JSON are produced in one read-only call.
    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        uint256 seed = seedOf(tokenId);
        GenerativeVideo.Recipe memory r = renderer.recipe(seed);
        string memory attributes = string.concat(
            '[{"trait_type":"Ball Count","value":',
            r.ballCount.toString(),
            '},{"trait_type":"Art Version","value":"GHOULBALLS_VAPOR_V3"},',
            '{"trait_type":"Theme","value":"',
            renderer.themeName(r.theme),
            '"},{"trait_type":"Motion","value":"',
            renderer.motionName(r.motion),
            '"},{"trait_type":"Seed","value":"',
            seed.toString(),
            '"},{"trait_type":"Duration Seconds","value":2},{"trait_type":"FPS","value":10}'
        );
        for (uint256 i; i < r.balls.length; ++i) {
            attributes = string.concat(
                attributes,
                ',{"trait_type":"Ball ',
                (i + 1).toString(),
                ' Colour","value":"',
                Strings.toHexString(uint256(uint24(r.balls[i].colour)), 3),
                '"},{"trait_type":"Ball ',
                (i + 1).toString(),
                ' Radius","value":',
                r.balls[i].radius.toString(),
                "}"
            );
        }
        bytes memory metadata = abi.encodePacked(
            '{"name":"',
            COLLECTION_NAME,
            " #",
            tokenId.toString(),
            '","description":"A two-second generative vaporwave loop with neon balls: an animated GIF rendered entirely in Solidity.",',
            '"image":"',
            imageURI(tokenId),
            '","attributes":',
            attributes,
            "]}"
        );
        return string.concat("data:application/json;base64,", Base64.encode(metadata));
    }
}

src/Vaporwave.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

/// @dev Version-two artwork, isolated from the original scene experiments.
abstract contract Vaporwave {
    function _vaporKey(uint256 seed) internal pure returns (uint256) {
        return uint256(keccak256(abi.encode("GHOULBALLS_VAPOR_V3", seed)));
    }

    function _vaporPalette(uint256 seed) internal pure returns (bytes memory palette) {
        uint256 key = _vaporKey(seed);
        uint256 theme = (key >> 8) % 4;
        bytes memory sky = bytes(
            theme == 0
                ? hex"08081915102e29134552245c7a3ab0ea5cb4ffbf9ba8fff0"
                : theme == 1
                    ? hex"050e210b183818295a3e3d70327ab0d559c7ffcaad94fff0"
                    : theme == 2
                        ? hex"13091f29113546184176264f9250bcf26d9bffd18cd5b9ff"
                        : hex"160b262c153b55214e9039587e55adff8eb8ffe3a39ef5ed"
        );
        palette = new bytes(48);
        for (uint256 i; i < 24; ++i) {
            palette[i] = sky[i];
        }
        // Ball i's colour comes from its own hash: any hue, neon-range saturation and brightness.
        for (uint256 i; i < 6; ++i) {
            (uint256 r, uint256 g, uint256 b) = _neon(uint256(keccak256(abi.encode(seed, i))));
            palette[24 + 3 * i] = bytes1(uint8(r));
            palette[25 + 3 * i] = bytes1(uint8(g));
            palette[26 + 3 * i] = bytes1(uint8(b));
        }
        palette[42] = 0x4a;
        palette[43] = 0x37;
        palette[44] = 0x6f;
        palette[45] = 0xf5;
        palette[46] = 0xff;
        palette[47] = 0xf3;
    }

    /// @dev Integer HSV to RGB: hue 0..359, saturation 120..229, value 220..255 (all /255).
    function _neon(uint256 hash) internal pure returns (uint256 r, uint256 g, uint256 b) {
        uint256 hue = (hash >> 136) % 360;
        uint256 s = 120 + (hash >> 152) % 110;
        uint256 v = 220 + (hash >> 168) % 36;
        uint256 rem = (hue % 60) * 255 / 60;
        uint256 p = v * (255 - s) / 255;
        uint256 q = v * (255 - s * rem / 255) / 255;
        uint256 t = v * (255 - s * (255 - rem) / 255) / 255;
        uint256 region = hue / 60;
        if (region == 0) return (v, t, p);
        if (region == 1) return (q, v, p);
        if (region == 2) return (p, v, t);
        if (region == 3) return (p, q, v);
        if (region == 4) return (t, p, v);
        return (v, p, q);
    }

    function _vaporBackdrop(uint256 size, uint256 seed) internal pure returns (bytes memory pixels) {
        uint256 key = _vaporKey(seed);
        pixels = new bytes(size * size);
        assembly ("memory-safe") {
            let shift := and(key, 63)
            let sunX := add(19, mod(shr(32, key), 27))
            let dst := add(pixels, 32)
            for { let yy := 0 } lt(yy, size) { yy := add(yy, 1) } {
                let y := div(mul(yy, 64), size)
                for { let xx := 0 } lt(xx, size) { xx := add(xx, 1) } {
                    let x := div(mul(xx, 64), size)
                    let c := add(1, div(y, 14))
                    let dx := sub(x, sunX)
                    let dy := sub(y, 22)
                    if lt(add(mul(dx, dx), mul(dy, dy)), 100) {
                        c := 6
                        if and(gt(y, 22), lt(mod(y, 4), 2)) { c := 3 }
                    }
                    if and(lt(y, 29), iszero(mod(add(add(mul(x, 73), mul(y, 37)), shift), 211))) { c := 7 }
                    // Low silhouetted mountains against the horizon.
                    let ridge := mod(add(x, shift), 32)
                    if gt(ridge, 16) { ridge := sub(32, ridge) }
                    if and(gt(y, sub(39, div(ridge, 3))), lt(y, 41)) { c := 0 }
                    if gt(y, 40) {
                        c := 0
                        let depth := sub(y, 40)
                        let distance := sub(x, 32)
                        if lt(x, 32) { distance := sub(32, x) }
                        if lt(mod(mul(distance, 16), add(depth, 4)), 2) { c := 4 }
                    }
                    mstore8(add(dst, add(mul(yy, size), xx)), c)
                }
            }
        }
    }

    function _drawVapor(
        bytes memory pixels,
        uint256 size,
        uint256 f,
        uint256 frames,
        uint256 scene,
        uint256 seed,
        bytes memory background
    ) internal pure {
        uint256 key = _vaporKey(seed);
        assembly ("memory-safe") {
            function bounce(start, offset, span) -> value {
                let p := mod(add(start, offset), mul(span, 2))
                value := p
                if gt(p, span) { value := sub(mul(span, 2), p) }
            }
            // Signed smooth periodic curve, +/-1024. Integer parabolic sine approximation.
            function wave(t) -> value {
                t := mod(t, 128)
                let p := mod(t, 64)
                value := mul(p, sub(64, p))
                if gt(t, 63) { value := sub(0, value) }
            }
            let phase := mod(div(mul(f, 128), frames), 128)
            let scroll := div(phase, 2)
            let dst := add(pixels, 32)
            mcopy(dst, add(background, 32), mload(pixels))
            // Only the floor's travelling scanlines change behind the balls.
            for { let yy := 0 } lt(yy, size) { yy := add(yy, 1) } {
                let y := div(mul(yy, 64), size)
                if gt(y, 40) {
                    let depth := sub(y, 40)
                    if lt(mod(add(mul(depth, depth), mul(scroll, 4)), 64), 4) {
                        let row := add(dst, mul(yy, size))
                        for { let xx := 0 } lt(xx, size) { xx := add(xx, 1) } { mstore8(add(row, xx), 5) }
                    }
                }
            }
            let count := 1
            switch scene
            case 8 { count := 2 }
            case 9 { count := 4 }
            case 10 { count := 6 }
            let style := mod(shr(16, key), 4)
            for { let ball := 0 } lt(ball, count) { ball := add(ball, 1) } {
                mstore(0, seed)
                mstore(32, ball)
                let hash := keccak256(0, 64)
                let radius := add(5, mod(shr(24, hash), 6))
                let span := sub(63, mul(radius, 2))
                let period := mul(span, 2)
                let startX := mod(shr(40, hash), period)
                let startY := mod(shr(72, hash), period)
                let offset := div(mul(period, mod(f, frames)), frames)
                let cx := add(radius, bounce(startX, offset, span))
                let cy := add(radius, bounce(startY, offset, span))
                let t := add(phase, mod(shr(104, hash), 128))
                switch style
                case 1 {
                    cx := add(32, sdiv(mul(wave(t), sub(25, radius)), 1024))
                    cy := add(30, sdiv(mul(wave(add(t, 32)), sub(23, radius)), 1024))
                }
                case 2 { cy := add(30, sdiv(mul(wave(t), sub(17, radius)), 1024)) }
                case 3 {
                    cx := add(32, sdiv(mul(wave(t), sub(25, radius)), 1024))
                    cy := add(31, sdiv(mul(wave(add(mul(t, 2), startY)), sub(23, radius)), 1024))
                }
                let x0 := div(add(mul(sub(cx, radius), size), 63), 64)
                let x1 := div(add(mul(add(add(cx, radius), 1), size), 63), 64)
                let y0 := div(add(mul(sub(cy, radius), size), 63), 64)
                let y1 := div(add(mul(add(add(cy, radius), 1), size), 63), 64)
                let rr := mul(radius, radius)
                for { let yy := y0 } lt(yy, y1) { yy := add(yy, 1) } {
                    let dy := sub(div(mul(yy, 64), size), cy)
                    let row := add(dst, mul(yy, size))
                    for { let xx := x0 } lt(xx, x1) { xx := add(xx, 1) } {
                        let dx := sub(div(mul(xx, 64), size), cx)
                        if iszero(gt(add(mul(dx, dx), mul(dy, dy)), rr)) {
                            let c := add(8, ball)
                            if and(sgt(dy, div(radius, 3)), sgt(dx, 0)) { c := 14 }
                            let hx := add(dx, div(radius, 3))
                            let hy := add(dy, div(radius, 3))
                            if lt(add(mul(hx, hx), mul(hy, hy)), div(rr, 9)) { c := 15 }
                            mstore8(add(row, xx), c)
                        }
                    }
                }
            }
        }
    }
}

