// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;
import {SceneKit} from "./SceneBase.sol";
import {Raster} from "./Raster.sol";
import {Epoch} from "./Epoch.sol";

/// @notice Integer perspective and palette tools for the 128px Neo-Tokyo translations.
library CityKit {
    using Epoch for bytes;

    struct Camera {
        int256 x;
        int256 y;
        int256 sy;
        int256 cy;
        int256 sp;
        int256 cp;
        int256 focal;
        int256 horizon;
    }

    function camera(int256 x, int256 y, int256 yaw, int256 pitch, int256 focal, int256 horizon)
        internal
        pure
        returns (Camera memory)
    {
        return Camera(
            x,
            y,
            SceneKit.sin(yaw),
            SceneKit.sin(yaw + 256),
            SceneKit.sin(pitch),
            SceneKit.sin(pitch + 256),
            focal,
            horizon
        );
    }

    struct Point {
        int256 x;
        int256 y;
        int256 z;
    }

    function palette(uint256 kind) internal pure returns (bytes memory) {
        uint24 fog = kind == 1 ? 0x142846 : kind == 2 ? 0x342052 : 0x461a60;
        uint24[16] memory ramps = [
            uint24(0),
            0x120c28,
            0x0b081a,
            0x24203a,
            0x1b142b,
            0,
            0,
            0,
            0,
            0,
            0,
            0xffbe6e,
            0xffaad0,
            0,
            0xc8d7ff,
            0x07060e
        ];
        bytes memory sky = new bytes(48);
        for (uint256 i; i < 16; ++i) {
            uint24 top = kind == 1 ? 0x030810 : 0x050310;
            uint24 end = kind == 1 ? 0x507090 : kind == 2 ? 0xf5a096 : 0xff70c0;
            for (uint256 c; c < 3; ++c) {
                uint256 shift = 16 - 8 * c;
                sky[3 * i + c] = bytes1(uint8((((top >> shift) & 255) * (15 - i) + ((end >> shift) & 255) * i) / 15));
            }
        }
        return SceneKit.palette(ramps, fog, 0x3c3450, sky, "");
    }

    /// @dev World coordinates in milli-units; y down, yaw/pitch in 1/1024 turns.
    /// @dev Scene positions are bounded milli-units (absolute value < 1,000,000), focal <= 128.
    ///      Trig coefficients are precomputed once per camera; fixed-point intermediates fit comfortably in int256.
    function project(Camera memory cam, int256 x, int256 y, int256 z) internal pure returns (Point memory p) {
        p = Point(0, 0, 0);
        assembly ("memory-safe") {
            let dx := sub(x, mload(cam))
            let dy := sub(y, mload(add(cam, 32)))
            let sy := mload(add(cam, 64))
            let cy := mload(add(cam, 96))
            let sp := mload(add(cam, 128))
            let cp := mload(add(cam, 160))
            let rx := sdiv(sub(mul(dx, cy), mul(z, sy)), 1024)
            let rz := sdiv(add(mul(dx, sy), mul(z, cy)), 1024)
            let ry := sdiv(sub(mul(dy, cp), mul(rz, sp)), 1024)
            let depth := sdiv(add(mul(dy, sp), mul(rz, cp)), 1024)
            mstore(add(p, 64), depth)
            if sgt(depth, 180) {
                let focal := mload(add(cam, 192))
                mstore(p, add(64, sdiv(mul(rx, focal), depth)))
                mstore(add(p, 32), add(mload(add(cam, 224)), sdiv(mul(ry, focal), depth)))
            }
        }
    }

    function quad(uint256 p, Point memory a, Point memory b, Point memory c, Point memory d, uint256 colour)
        internal
        pure
    {
        if (a.z <= 180 || b.z <= 180 || c.z <= 180 || d.z <= 180) return;
        Raster.quadPixels(p, [a.x, a.y, b.x, b.y, c.x, c.y, d.x, d.y], colour);
    }

    /// @dev Two visible box faces and roof; windows are verified bloom/hash bits, never an RPC transaction count.
    function tower(
        uint256 p,
        bytes memory e,
        uint256 i,
        Camera memory cam,
        int256 x,
        int256 z,
        int256 half,
        int256 top,
        int256 bottom,
        uint256 fog,
        uint256 rows
    ) internal pure returns (Point memory roof) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            Point memory a = project(cam, x - half, top, z - half);
            Point memory b = project(cam, x + half, top, z - half);
            Point memory c = project(cam, x + half, bottom, z - half);
            Point memory d = project(cam, x - half, bottom, z - half);
            quad(p, a, b, c, d, 16 + fog);
            bool right = x < cam.x;
            Point memory s = project(cam, right ? x + half : x - half, top, z + half);
            Point memory t = project(cam, right ? x + half : x - half, bottom, z + half);
            quad(p, right ? b : a, s, t, right ? c : d, 32 + fog);
            Point memory far = project(cam, right ? x - half : x + half, top, z + half);
            quad(p, a, b, right ? s : far, right ? far : s, 48 + fog);
            uint256 neon = (5 + e.neon(i)) * 16 + fog / 2;
            if (a.z > 180 && b.z > 180) Raster.line(p, a.x, a.y, b.x, b.y, neon);
            if (s.z > 180 && a.z > 180 && b.z > 180) {
                Raster.line(p, right ? b.x : a.x, right ? b.y : a.y, s.x, s.y, neon);
            }
            if (a.z > 180 && b.z > 180 && a.x < 128 && b.x >= 0) {
                for (uint256 r; r < rows; ++r) {
                    for (uint256 q; q < 4; ++q) {
                        uint256 bit = r * 4 + q;
                        if (!e.bloomBit(i, bit * 3 + i) || !e.hashBit(i, bit)) continue;
                        int256 wx = a.x + (b.x - a.x) * int256(2 * q + 1) / 8;
                        int256 wy = a.y + (d.y - a.y) * int256(2 * r + 1) / int256(2 * rows);
                        Raster.rect(p, wx, wy, wx + 1, wy + 1, (e.stateByte(i, bit) & 1 == 1 ? 176 : 208) + fog);
                    }
                }
            }
            roof = project(cam, x, top, z);
        }
    }

    function activity(bytes memory e, uint256 i, uint256 base, uint256 extra) internal pure returns (uint256) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            uint256 used = e.gasBps(i);
            if (used > 10000) used = 10000;
            return base + used * extra / 10000;
        }
    }

    function traffic(uint256 p, bytes memory e, uint256 f, uint256 count, int256 horizon) internal pure {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            for (uint256 k; k < count; ++k) {
                int256 x = SceneKit.wrap(
                    int256(e.hashByte(k % 10, k)) + int256(f) * 148 * (k % 2 == 0 ? int256(1) : int256(-1)) / 90, 148
                ) - 10;
                int256 y = horizon + 8 + int256(e.hashByte(k % 10, k + 7) % 22);
                Raster.line(p, x, y, x + 3, y, k % 2 == 0 ? 208 : 160);
            }
        }
    }
}

src/blockart/DataURI.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

/// @notice Builds `data:application/json;base64,` + base64(pre + base64(gif) + post) in one allocation.
/// @dev The token JSON embeds the GIF as base64 and is itself base64-encoded, so the GIF is encoded twice. Holding the
///      inner encoding, the JSON and the final URI as separate strings would keep ~4x the GIF size alive, and EVM
///      memory cost is quadratic. Instead the JSON stream is produced into a small window and outer-encoded as it
///      fills: live memory is just the GIF and the final URI.
///      Base64 is word-parallel: 24 input bytes -> 32 characters per step. Five masked shifts spread the 6-bit fields
///      into byte lanes; lane-wise compares (add, test the high bit) pick each lane's ASCII offset with no table.
library DataURI {
    uint256 private constant WINDOW = 3072; // 128 x 24 input bytes per flush

    function jsonWithGif(bytes memory pre, bytes memory gif, bytes memory post)
        internal
        pure
        returns (string memory out)
    {
        uint256 total = pre.length + 4 * ((gif.length + 2) / 3) + post.length;
        bytes memory head = "data:application/json;base64,";
        out = new string(head.length + 4 * ((total + 2) / 3));
        bytes memory window = new bytes(WINDOW + 64);
        assembly ("memory-safe") {
            // 24 bytes at the top of v -> 32 base64 characters.
            function b64(v) -> r {
                v := shr(2, and(v, 0xffffffffffffffffffffffffffffffffffffffffffffffff0000000000000000))
                v := or(
                    and(v, 0x3fffffffffffffffffffffffc000000000000000000000000000000000000000),
                    shr(32, and(v, 0x3fffffffffffffffffffffffc000000000000000))
                )
                v := or(
                    and(v, 0x3fffffffffffc00000000000000000003fffffffffffc0000000000000000000),
                    shr(16, and(v, 0x3fffffffffffc00000000000000000003fffffffffffc0000000))
                )
                v := or(
                    and(v, 0x3fffffc0000000003fffffc0000000003fffffc0000000003fffffc000000000),
                    shr(8, and(v, 0x3fffffc0000000003fffffc0000000003fffffc0000000003fffffc000))
                )
                v := or(
                    and(v, 0x3ffc00003ffc00003ffc00003ffc00003ffc00003ffc00003ffc00003ffc0000),
                    shr(4, and(v, 0x3ffc00003ffc00003ffc00003ffc00003ffc00003ffc00003ffc00003ffc0))
                )
                v := or(
                    and(v, 0x3f003f003f003f003f003f003f003f003f003f003f003f003f003f003f003f00),
                    shr(2, and(v, 0xfc00fc00fc00fc00fc00fc00fc00fc00fc00fc00fc00fc00fc00fc00fc00fc))
                )
                let h := 0x8080808080808080808080808080808080808080808080808080808080808080
                let ge26 := shr(7, and(add(v, 0x6666666666666666666666666666666666666666666666666666666666666666), h))
                let ge52 := shr(7, and(add(v, 0x4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c4c), h))
                let ge62 := shr(7, and(add(v, 0x4242424242424242424242424242424242424242424242424242424242424242), h))
                let ge63 := shr(7, and(add(v, 0x4141414141414141414141414141414141414141414141414141414141414141), h))
                // 'A'+v, 'a'-26+v, '0'-52+v, '+', '/': base 65, +6, -75, -15, +3, with no lane carries or borrows.
                r := sub(
                    add(
                        add(add(v, 0x4141414141414141414141414141414141414141414141414141414141414141), mul(ge26, 6)),
                        mul(ge63, 3)
                    ),
                    add(mul(ge52, 75), mul(ge62, 15))
                )
            }
            // Encode len bytes at src to dst, '=' padded; returns the advanced dst.
            function encode(src, len, dst) -> d {
                let end := add(src, sub(len, mod(len, 24)))
                for {} lt(src, end) {} {
                    mstore(dst, b64(mload(src)))
                    src := add(src, 24)
                    dst := add(dst, 32)
                }
                let r := mod(len, 24)
                d := dst
                if r {
                    mstore(dst, b64(and(mload(src), not(shr(shl(3, r), not(0))))))
                    let chars := mul(4, div(add(r, 2), 3))
                    d := add(dst, chars)
                    switch mod(r, 3)
                    case 1 {
                        mstore8(sub(d, 2), 0x3d)
                        mstore8(sub(d, 1), 0x3d)
                    }
                    case 2 { mstore8(sub(d, 1), 0x3d) }
                }
            }
            // Append raw bytes to the window, flushing full windows to dst.
            function append(src, len, win, pending, dst) -> p, d {
                p := pending
                d := dst
                for {} len {} {
                    let take := sub(3072, p)
                    if lt(len, take) { take := len }
                    mcopy(add(win, p), src, take)
                    p := add(p, take)
                    src := add(src, take)
                    len := sub(len, take)
                    if eq(p, 3072) {
                        d := encode(win, 3072, d)
                        p := 0
                    }
                }
            }

            let fmp := mload(0x40)
            mcopy(add(out, 32), add(head, 32), mload(head))
            let o := add(add(out, 32), mload(head))
            let w := add(window, 32)
            let n := 0

            n, o := append(add(pre, 32), mload(pre), w, n, o)
            // Inner encoding: 24 GIF bytes -> 32 characters straight into the window.
            {
                let src := add(gif, 32)
                let len := mload(gif)
                let end := add(src, sub(len, mod(len, 24)))
                for {} lt(src, end) {} {
                    mstore(add(w, n), b64(mload(src)))
                    src := add(src, 24)
                    n := add(n, 32)
                    if iszero(lt(n, 3072)) {
                        o := encode(w, 3072, o)
                        n := sub(n, 3072)
                        mstore(w, mload(add(w, 3072))) // carry the overrun
                    }
                }
                let r := mod(len, 24)
                if r {
                    let t := fmp // scratch beyond all allocations
                    let e := encode(src, r, t)
                    n, o := append(t, sub(e, t), w, n, o)
                }
            }
            n, o := append(add(post, 32), mload(post), w, n, o)
            o := encode(w, n, o)
        }
    }
}

src/blockart/Epoch.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

/// @notice Read-only accessors over a packed 10-block epoch record (see BlockHeaders.verifyEpoch).
/// @dev Record i starts at i * 352: meta word (number | gasUsed | gasLimit | timestamp, 64 bits each), block hash,
///      state root, 256-byte logs bloom. Mirrors `block()` in concepts/neo-tokyo/kit.js.
library Epoch {
    uint256 internal constant N = 10;
    uint256 internal constant RECORD = 352;

    function _word(bytes memory e, uint256 i, uint256 off) private pure returns (uint256 v) {
        assembly ("memory-safe") {
            v := mload(add(add(add(e, 32), mul(i, 352)), off))
        }
    }

    function number(bytes memory e, uint256 i) internal pure returns (uint256) {
        return _word(e, i, 0) >> 192;
    }

    /// @dev Gas used as a fraction of the gas limit, in 1/10000 (basis points).
    function gasBps(bytes memory e, uint256 i) internal pure returns (uint256) {
        uint256 m = _word(e, i, 0);
        uint256 limit = (m >> 64) & type(uint64).max;
        return limit == 0 ? 0 : ((m >> 128) & type(uint64).max) * 10000 / limit;
    }

    function hash(bytes memory e, uint256 i) internal pure returns (uint256) {
        return _word(e, i, 32);
    }

    function hashByte(bytes memory e, uint256 i, uint256 k) internal pure returns (uint256) {
        return (_word(e, i, 32) >> (8 * (31 - (k % 32)))) & 0xff;
    }

    function stateByte(bytes memory e, uint256 i, uint256 k) internal pure returns (uint256) {
        return (_word(e, i, 64) >> (8 * (31 - (k % 32)))) & 0xff;
    }

    /// @dev Bit `k` of the hash, counted from the most significant bit of byte 0 (kit.js `bit`).
    function hashBit(bytes memory e, uint256 i, uint256 k) internal pure returns (bool) {
        return (_word(e, i, 32) >> (255 - (k % 256))) & 1 == 1;
    }

    function bloomBit(bytes memory e, uint256 i, uint256 k) internal pure returns (bool r) {
        assembly ("memory-safe") {
            let b := byte(0, mload(add(add(add(e, 32), mul(i, 352)), add(96, mod(shr(3, k), 256)))))
            r := and(shr(sub(7, and(k, 7)), b), 1)
        }
    }

    /// @dev Neon colour (0..5) and sign word (0..14) of block i, as in the concepts.
    function neon(bytes memory e, uint256 i) internal pure returns (uint256) {
        return hashByte(e, i, 3) % 6;
    }

    function word(bytes memory e, uint256 i) internal pure returns (uint256) {
        return hashByte(e, i, 5) % 15;
    }

    /// @notice Which scene an epoch mints: rare SATOYAMA (7) on ~1/64 epochs, else one of the seven regular scenes.
    function scene(bytes memory e) internal pure returns (uint256) {
        uint256 h = hash(e, N - 1);
        if ((h >> 216) & 0xff < 4) return 7;
        return (h >> 224) % 7;
    }
}

src/blockart/GifWriter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

/// @notice Looping GIF89a writer for 128x128 frames with a 256-colour palette.
/// @dev Pixels are stored as literal LZW codes (no compression) at a fixed 9-bit code size: a clear code starts every
///      group of 239 pixels, so the dictionary never grows past 9 bits. A group is 240 codes = ten blocks of 24 codes,
///      and 24 codes x 9 bits = 27 bytes, so each block packs with word operations: byte-swap 24 pixels into
///      little-endian order, spread the 8-bit fields to 9-bit slots with five masked shifts, byte-swap back, one mstore.
///      Frame delays alternate 7, 7, 6 centiseconds: exactly 15fps.
library GifWriter {
    uint256 internal constant PIXELS = 16384;
    uint256 internal constant GROUP = 239;
    uint256 internal constant FULL_GROUPS = PIXELS / GROUP; // 68
    uint256 internal constant TAIL = PIXELS - FULL_GROUPS * GROUP; // 132
    /// @dev Codes per frame: full groups, the last group's clear + tail pixels, and end-of-information.
    uint256 internal constant CODES = FULL_GROUPS * (GROUP + 1) + 1 + TAIL + 1;
    uint256 internal constant LZW_BYTES = (CODES * 9 + 7) / 8; // 18,511
    uint256 internal constant SUB_BLOCKS = (LZW_BYTES + 254) / 255; // 73
    /// @dev Graphic control (8) + image descriptor (10) + min code size (1) + data + length bytes + terminator.
    uint256 internal constant FRAME_BYTES = 8 + 10 + 1 + LZW_BYTES + SUB_BLOCKS + 1;
    uint256 internal constant HEADER_BYTES = 6 + 7 + 768 + 19;

    function size(uint256 frames) internal pure returns (uint256) {
        return HEADER_BYTES + frames * FRAME_BYTES + 1;
    }

    /// @notice Allocate the whole file and write its header, palette and loop extension. Returns the write position.
    function start(uint256 frames, bytes memory palette) internal pure returns (bytes memory out, uint256 pos) {
        require(palette.length == 768);
        out = new bytes(size(frames));
        assembly ("memory-safe") {
            let o := add(out, 32)
            // "GIF89a", 128x128, global colour table of 256 entries (flags 0xf7), background 0, aspect 0.
            mstore(o, shl(152, 0x47494638396180008000f70000))
            mcopy(add(o, 13), add(palette, 32), 768)
            // NETSCAPE2.0 application extension: loop forever.
            let n := add(o, 781)
            mstore(n, shl(104, 0x21ff0b4e45545343415045322e300301000000))
        }
        pos = HEADER_BYTES;
    }

    /// @notice Append frame `f` (its pixels at memory pointer `px`) at `pos`; `scratch` holds LZW_BYTES + 32.
    function frame(bytes memory out, uint256 pos, uint256 px, uint256 f, bytes memory scratch)
        internal
        pure
        returns (uint256)
    {
        assembly ("memory-safe") {
            function bswap(x) -> y {
                x := or(
                    shr(8, and(x, 0xff00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff00)),
                    shl(8, and(x, 0x00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff00ff))
                )
                x := or(
                    shr(16, and(x, 0xffff0000ffff0000ffff0000ffff0000ffff0000ffff0000ffff0000ffff0000)),
                    shl(16, and(x, 0x0000ffff0000ffff0000ffff0000ffff0000ffff0000ffff0000ffff0000ffff))
                )
                x := or(
                    shr(32, and(x, 0xffffffff00000000ffffffff00000000ffffffff00000000ffffffff00000000)),
                    shl(32, and(x, 0x00000000ffffffff00000000ffffffff00000000ffffffff00000000ffffffff))
                )
                x := or(
                    shr(64, and(x, 0xffffffffffffffff0000000000000000ffffffffffffffff0000000000000000)),
                    shl(64, and(x, 0x0000000000000000ffffffffffffffff0000000000000000ffffffffffffffff))
                )
                y := or(shr(128, x), shl(128, x))
            }
            // Move 8-bit field i (at bit 8i) to bit 9i, i = 0..23.
            function spread(v) -> r {
                v := or(
                    and(v, 0xffffffffffffffffffffffffffffffff),
                    shl(16, and(v, 0xffffffffffffffff00000000000000000000000000000000))
                )
                v := or(
                    and(v, 0xffffffffffffffff00000000000000000000ffffffffffffffff),
                    shl(8, and(v, 0xffffffffffffffff0000000000000000))
                )
                v := or(
                    and(v, 0xffffffff0000000000ffffffff0000000000ffffffff),
                    shl(4, and(v, 0xffffffff0000000000ffffffff0000000000ffffffff00000000))
                )
                v := or(
                    and(v, 0xffff00000ffff00000ffff00000ffff00000ffff00000ffff),
                    shl(2, and(v, 0xffff00000ffff00000ffff00000ffff00000ffff00000ffff0000))
                )
                r := or(
                    and(v, 0x3fc00ff003fc00ff003fc00ff003fc00ff003fc00ff003fc00ff),
                    shl(1, and(v, 0x3fc00ff003fc00ff003fc00ff003fc00ff003fc00ff003fc00ff00))
                )
            }
            let w := add(scratch, 32)
            for { let g := 0 } lt(g, 68) { g := add(g, 1) } {
                // Block 0: clear code, then 23 pixels.
                mstore(
                    w,
                    bswap(
                        or(spread(shl(8, and(bswap(mload(px)), 0xffffffffffffffffffffffffffffffffffffffffffffff))), 256)
                    )
                )
                w := add(w, 27)
                px := add(px, 23)
                for { let k := 0 } lt(k, 9) { k := add(k, 1) } {
                    mstore(w, bswap(spread(and(bswap(mload(px)), 0xffffffffffffffffffffffffffffffffffffffffffffffff))))
                    w := add(w, 27)
                    px := add(px, 24)
                }
            }
            // Last group: clear, 132 pixels, end-of-information, through a plain bit accumulator.
            let acc := 256
            let nb := 9
            for { let k := 0 } lt(k, 133) { k := add(k, 1) } {
                let code := 257
                if lt(k, 132) { code := byte(0, mload(add(px, k))) }
                acc := or(acc, shl(nb, code))
                nb := add(nb, 9)
                for {} gt(nb, 7) {} {
                    mstore8(w, acc)
                    w := add(w, 1)
                    acc := shr(8, acc)
                    nb := sub(nb, 8)
                }
            }
            if nb { mstore8(w, acc) }
        }
        assembly ("memory-safe") {
            let o := add(add(out, 32), pos)
            // Graphic control extension: no transparency, delay 7/7/6 cs; image descriptor 128x128, no local table.
            let delay := 7
            if eq(mod(f, 3), 2) { delay := 6 }
            mstore8(o, 0x21)
            mstore8(add(o, 1), 0xf9)
            mstore8(add(o, 2), 4)
            mstore8(add(o, 3), 4) // disposal: do not dispose
            mstore8(add(o, 4), delay)
            mstore8(add(o, 5), 0)
            mstore8(add(o, 6), 0)
            mstore8(add(o, 7), 0)
            mstore8(add(o, 8), 0x2c)
            mstore8(add(o, 9), 0)
            mstore8(add(o, 10), 0)
            mstore8(add(o, 11), 0)
            mstore8(add(o, 12), 0)
            mstore8(add(o, 13), 128)
            mstore8(add(o, 14), 0)
            mstore8(add(o, 15), 128)
            mstore8(add(o, 16), 0)
            mstore8(add(o, 17), 0)
            mstore8(add(o, 18), 8) // LZW minimum code size
            o := add(o, 19)
            let src := add(scratch, 32)
            let left := 18511
            for {} left {} {
                let n := 255
                if lt(left, 255) { n := left }
                mstore8(o, n)
                mcopy(add(o, 1), src, n)
                o := add(o, add(n, 1))
                src := add(src, n)
                left := sub(left, n)
            }
            mstore8(o, 0)
        }
        return pos + FRAME_BYTES;
    }

    function finish(bytes memory out, uint256 pos) internal pure {
        out[pos] = 0x3b;
        assert(pos + 1 == out.length);
    }
}

