// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;
import {Raster} from "../Raster.sol";
import {Epoch} from "../Epoch.sol";
import {SceneBase, SceneKit} from "../SceneBase.sol";
import {CityKit} from "../CityKit.sol";

/// @notice 路地 ALLEY: wet corridor, hash-selected neon signs, bloom windows, paper lanterns and a hash vending machine.
contract Alley is SceneBase {
    using Epoch for bytes;

    function _palette(bytes memory) internal pure override returns (bytes memory) {
        return CityKit.palette(0);
    }

    function _backdrop(uint256 p, bytes memory) internal pure override {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            SceneKit.sky(p, 0, 160, 56, 16, 64, 56, 48, 6);
            Raster.quadPixels(p, [-int256(30), -300, int256(59), 31, int256(59), 62, -30, 180], 17);
            Raster.quadPixels(p, [int256(69), 31, int256(158), -300, int256(158), 180, int256(69), 62], 33);
            Raster.quadPixels(p, [int256(59), 62, int256(69), 62, int256(128), 128, int256(0), 128], 242);
        }
    }

    function _x(int256 side, int256 z) private pure returns (int256) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            return 64 + side * 41000 / z;
        }
    }

    function _y(int256 y, int256 z) private pure returns (int256) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            return 56 + y * 41 / z;
        }
    }

    function _draw(uint256 p, bytes memory e, uint256[] memory, uint256 f) internal pure override {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            int256 cam = int256(f) * 10000 / 90;
            uint256 first = uint256(cam / 1000);
            for (uint256 k = 10; k > 0; --k) {
                uint256 i = (first + k) % 10;
                int256 z = SceneKit.wrap(int256(i) * 1000 - cam, 10000) + 450;
                if (z > 9700) continue;
                uint256 fog = SceneKit.fog(z, 450, 9700);
                for (int256 side = -1; side <= 1; side += 2) {
                    int256 sx = _x(side, z);
                    Raster.line(p, sx, _y(-6000, z), sx, _y(1250, z), 240 + fog / 2);
                    for (uint256 r; r < 10; ++r) {
                        for (uint256 q; q < 3; ++q) {
                            uint256 bit = r * 3 + q + (side > 0 ? 64 : 0);
                            if (!e.bloomBit(i, bit * 5 + i) || !e.hashBit(i, bit)) continue;
                            int256 zz = z + int256(q) * 280 + 85;
                            int256 x = _x(side, zz);
                            int256 y = _y(-5600 + int256(r) * 420, zz);
                            Raster.rect(p, x, y, x + 1, y + 2, (e.stateByte(i, bit) & 1 == 1 ? 176 : 208) + fog);
                        }
                    }
                }
                int256 s = e.hashByte(i, 2) & 1 == 1 ? int256(1) : int256(-1);
                int256 fs = 12300 / (z + 150);
                if (fs < 3) fs = 3;
                if (fs > 11) fs = 11;
                int256 sx = 64 + s * 32000 / (z + 150);
                int256 sy = _y(-2600 + int256(e.hashByte(i, 4)) * 1200 / 255, z + 150);
                SceneKit.verticalSign(p, e.word(i), sx, sy, fs, 5 + e.neon(i), fog / 2);
                // Short, dithered reflections in the wet floor, in this block's own neon colour.
                int256 reflection = 64 + s * 22000 / (z + 500);
                for (uint256 r; r < 3; ++r) {
                    Raster.rect(
                        p,
                        reflection - 1,
                        _y(1250, z) + int256(r) * 3,
                        reflection + 2,
                        _y(1250, z) + int256(r) * 3 + 1,
                        (5 + e.neon(i)) * 16 + 8 + r
                    );
                }
                if (e.hashByte(i, 9) % 2 == 0) {
                    int256 zz = z + 500;
                    int256 yy = _y(-1600, zz);
                    Raster.line(p, _x(-1, zz), yy, 64, yy + 3, 240 + fog / 2);
                    Raster.line(p, 64, yy + 3, _x(1, zz), yy, 240 + fog / 2);
                    int256 radius = 2800 / zz;
                    if (radius < 1) radius = 1;
                    for (int256 q = -1; q <= 1; ++q) {
                        Raster.disc(p, 64 + q * 18000 / zz, yy + 5, radius, 160 + fog / 2);
                    }
                }
            }
            uint256 cur = SceneKit.turn(f, 300);
            SceneKit.hologram(p, e, cur, 64, 3);
            // Vending machine's 8x8 hash panel and state-root buttons.
            Raster.rect(p, 5, 65, 25, 108, 33);
            Raster.rect(p, 7, 68, 23, 91, 98);
            for (uint256 r; r < 8; ++r) {
                for (uint256 q; q < 8; ++q) {
                    if (e.hashBit(cur, r * 8 + q)) Raster.dot(p, 8 + int256(q) * 2, 70 + int256(r) * 2, 209);
                }
            }
            for (uint256 k; k < 8; ++k) {
                Raster.rect(
                    p,
                    8 + int256(k % 4) * 4,
                    96 + int256(k / 4) * 4,
                    10 + int256(k % 4) * 4,
                    98 + int256(k / 4) * 4,
                    (5 + e.stateByte(cur, k) % 6) * 16
                );
            }
            SceneKit.rain(p, e, f, 45, 1, 232);
        }
    }
}

src/blockart/scenes/Canyon.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {Raster} from "../Raster.sol";
import {Glyphs} from "../Glyphs.sol";
import {Epoch} from "../Epoch.sol";
import {SceneBase, SceneKit} from "../SceneBase.sol";

/// @notice 峡谷 CANYON: the camera glides down a megacity street canyon; each block of the epoch is a building it passes
///         (vertical neon sign with its word, windows from its logs bloom, a skybridge every fourth block). The block
///         just ahead floats as a ベース・ブロック hologram. 128x128, 90 frames at 15fps, one seamless 6-second loop.
/// @dev Port of concepts/neo-tokyo/canyon.js. World units are milli-units; the camera moves 16 units (10 blocks x 1.6)
///      per loop. Palette: 16 ramps x 16 shades; shade = distance fog toward FOG.
contract Canyon is SceneBase {
    using Epoch for bytes;

    uint256 private constant FRAMES = SceneKit.FRAMES;
    int256 private constant NEAR = 320;
    int256 private constant FAR = 14000;
    int256 private constant SP = 1600;
    int256 private constant D = 16000;
    int256 private constant STREET = 3200;
    int256 private constant CANYON = 1250;
    int256 private constant DEPTH = 1312; // 0.82 * SP
    int256 private constant VX16 = 1024; // 64 px
    int256 private constant VY16 = 819; // 0.4 * 128 px
    int256 private constant F16 = 832; // focal length 52 px, in 1/16 px

    // Ramps.
    uint256 private constant SKY = 0;
    uint256 private constant WALL = 1;
    uint256 private constant FRONT = 2;
    uint256 private constant WARM = 3;
    uint256 private constant COOL = 4;
    uint256 private constant NEON = 5; // 5..10
    uint256 private constant BRIDGE = 11;
    uint256 private constant LAMP = 12;
    uint256 private constant WHITE = 13;
    uint256 private constant RAIN = 14;
    uint256 private constant DARK = 15;

    struct Building {
        int256 side;
        int256 x0;
        int256 top;
        uint256 neon;
        uint256 word;
        uint256 lit; // bit k (k = row * 5 + column): window lit, from the logs bloom and hash
        uint256 warm; // bit k: warm (amber) rather than cool, from the state root
    }

    function _palette(bytes memory) internal pure override returns (bytes memory) {
        // Sky: dark zenith -> fog -> the pink glow at the vanishing point.
        return SceneKit.palette(
            [
                uint24(0),
                0x100a20, // wall
                0x0a0616, // front
                0xffbe6e, // warm window
                0x78dcff, // cool window
                0,
                0,
                0,
                0,
                0,
                0,
                0x140e28, // bridge
                0xffd28c, // lamp
                0,
                0xbed2ff, // rain
                0x020104 // dark
            ],
            0x46165c,
            0xff5ab4,
            hex"0603120e061d1708281f0b32280d3d3010483b135246165c671f6f892783aa3096c640a2e350aeff60baff88cfffafe4",
            ""
        );
    }

    /// @dev Static sky: vertical gradient plus a radial glow at the vanishing point.
    function _backdrop(uint256 p, bytes memory) internal pure override {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            SceneKit.sky(p, 0, 112, 51, 48, 64, 51, 58, 9);
        }
    }

    /// @dev Per building, 7 words: side, x0, top, neon, word, lit mask, warm mask.
    function _prepare(bytes memory e) internal pure override returns (uint256[] memory st) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            st = new uint256[](70);
            for (uint256 i; i < 10; ++i) {
                int256 side = e.hashByte(i, 0) & 1 == 1 ? int256(1) : -1;
                uint256 g = e.gasBps(i) * 7 / 3; // min(1, gas / 0.3) * 7000
                if (g > 7000) g = 7000;
                uint256 lit;
                uint256 warm;
                for (uint256 k; k < 150; ++k) {
                    if (e.bloomBit(i, k * 3 + i) && e.hashBit(i, k)) lit |= 1 << k;
                    if (e.stateByte(i, k % 32) & 1 == 1) warm |= 1 << k;
                }
                st[i * 7] = uint256(side);
                st[i * 7 + 1] = uint256(side * (CANYON + int256(e.hashByte(i, 1)) * 350 / 255));
                st[i * 7 + 2] = uint256(-2400 - int256(g) - int256(e.hashByte(i, 2)) * 2000 / 255);
                st[i * 7 + 3] = e.neon(i);
                st[i * 7 + 4] = e.word(i);
                st[i * 7 + 5] = lit;
                st[i * 7 + 6] = warm;
            }
        }
    }

    function _b(uint256[] memory st, uint256 i) internal pure returns (Building memory b) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            b.side = int256(st[i * 7]);
            b.x0 = int256(st[i * 7 + 1]);
            b.top = int256(st[i * 7 + 2]);
            b.neon = st[i * 7 + 3];
            b.word = st[i * 7 + 4];
            b.lit = st[i * 7 + 5];
            b.warm = st[i * 7 + 6];
        }
    }

    function _fog(int256 dz) internal pure returns (uint256) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            return SceneKit.fog(dz, NEAR, FAR);
        }
    }

    /// @dev World point -> screen, in 1/16 px.
    function _px(int256 x, int256 dz) internal pure returns (int256) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            return VX16 + x * F16 / dz;
        }
    }

    function _py(int256 y, int256 dz) internal pure returns (int256) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            return VY16 + y * F16 / dz;
        }
    }

    function _wrap(int256 x, int256 m) internal pure returns (int256) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            return SceneKit.wrap(x, m);
        }
    }

    function _draw(uint256 p, bytes memory e, uint256[] memory st, uint256 f) internal pure override {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            int256 camZ = int256(f) * D / int256(FRAMES);
            _street(p, f);
            // Buildings, far to near.
            int256[10] memory dzs;
            uint256[10] memory order;
            uint256 count;
            for (uint256 i; i < 10; ++i) {
                int256 dz = _wrap(int256(i) * SP - camZ, D);
                if (dz < NEAR) dz += D;
                if (dz > FAR) continue;
                uint256 j = count++;
                while (j > 0 && dzs[j - 1] < dz) {
                    dzs[j] = dzs[j - 1];
                    order[j] = order[j - 1];
                    --j;
                }
                dzs[j] = dz;
                order[j] = i;
            }
            for (uint256 k; k < count; ++k) {
                _building(p, e, _b(st, order[k]), order[k], dzs[k], f);
            }
            _traffic(p, e, f);
            SceneKit.hologram(p, e, SceneKit.turn(f, 400), 64, 3);
            SceneKit.rain(p, e, f, 60, 1, RAIN * 16 + 6);
            _ledge(p, f);
        }
    }

    /// @dev Rivers of tail lights and headlights on the street far below, flowing toward the vanishing point.
    function _street(uint256 p, uint256 f) internal pure {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            for (uint256 k; k < 60; ++k) {
                int256 lane = (int256(k % 4) * 2 - 3) * 140;
                int256 dir = k % 2 == 1 ? int256(1) : -1;
                int256 z =
                    _wrap(int256(k) * 370 + dir * int256(f) * FAR * int256(1 + k % 3) / int256(FRAMES), FAR) + NEAR;
                uint256 fog = _fog(z) * 8 / 10;
                Raster.dot(p, _px(lane, z) >> 4, _py(STREET, z) >> 4, (dir > 0 ? NEON + 5 : WHITE) * 16 + fog);
            }
        }
    }

    function _building(uint256 p, bytes memory e, Building memory b, uint256 i, int256 dz, uint256 f) internal pure {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            uint256 fog = _fog(dz);
            // Canyon-facing wall from dz to dz + DEPTH.
            int256 ax = _px(b.x0, dz);
            int256 cx = _px(b.x0, dz + DEPTH);
            Raster.quad(
                p,
                [ax, _py(b.top, dz), cx, _py(b.top, dz + DEPTH), cx, _py(STREET, dz + DEPTH), ax, _py(STREET, dz)],
                WALL * 16 + fog
            );
            // Front face, out to the frame edge.
            {
                int256 y0 = _py(b.top, dz) >> 4;
                int256 y1 = _py(STREET, dz) >> 4;
                if (b.side > 0) Raster.rect(p, ax >> 4, y0, 128, y1, FRONT * 16 + fog);
                else Raster.rect(p, 0, y0, ax >> 4, y1, FRONT * 16 + fog);
            }
            // Windows: lit where the bloom and hash agree; warm or cool from the state root. 30 rows x 5 columns.
            _windows(p, b, dz, fog * 85 / 100);
            _sign(p, e, b, i, dz, fog, f);
            // A horizontal number sign on the front face, legible only close up.
            if (dz < 1300) {
                int256 hx = _px(b.x0 + b.side * 900, dz) >> 4;
                int256 hy = _py(900 + int256(e.hashByte(i, 8)) * 900 / 255, dz) >> 4;
                Raster.number(p, hx, hy, e.number(i), (NEON + b.neon) * 16 + fog * 6 / 10);
            }
            // Every fourth block: a skybridge across the canyon with lights; a monorail crosses some of them.
            if (i % 4 == 0) {
                int256 y = -600 - int256(e.hashByte(i, 9)) * 800 / 255;
                int256 z = dz + 400;
                int256 lx = _px(-CANYON - 300, z) >> 4;
                int256 rx = _px(CANYON + 300, z) >> 4;
                int256 ly = _py(y, z) >> 4;
                int256 th = F16 * 70 / z / 16 + 1; // 0.07 units thick
                Raster.rect(p, lx, ly, rx, ly + th, BRIDGE * 16 + fog);
                for (int256 k; k < 18; ++k) {
                    Raster.dot(p, lx + (rx - lx) * k / 18, ly + th / 3, LAMP * 16 + fog);
                }
                if (e.hashByte(i, 10) & 1 == 1) {
                    int256 run = int256((f * 3 * 255 + uint256(e.hashByte(i, 11)) * FRAMES) % (FRAMES * 255));
                    int256 x = lx + (rx - lx) * (run * 18 / int256(FRAMES * 255) - 4) / 10;
                    int256 w = (rx - lx) * 45 / 100;
                    int256 h = th * 7 / 10 + 1;
                    Raster.rect(p, x, ly - h, x + w, ly, WHITE * 16 + fog);
                    Raster.rect(p, x, ly - h / 3 - 1, x + w, ly - h / 3, (NEON + 1) * 16 + fog);
                }
            }
            // Cables strung across the canyon, sagging.
            if (e.hashByte(i, 12) % 3 == 0) {
                int256 z = dz + 500;
                int256 ax2 = _px(-CANYON, z) >> 4;
                int256 ay = _py(-2000 + int256(e.hashByte(i, 13)) * 1000 / 128, z) >> 4;
                int256 bx = _px(CANYON, z) >> 4;
                int256 by = _py(-2000 + int256(e.hashByte(i, 14)) * 1000 / 128, z) >> 4;
                int256 sag = (ay > by ? ay : by) + 6000 / z;
                int256 px0 = ax2;
                int256 py0 = ay;
                for (int256 s = 1; s <= 6; ++s) {
                    // Quadratic Bezier through the sagging midpoint control.
                    int256 x1 = (ax2 * (6 - s) * (6 - s) + 2 * ((ax2 + bx) / 2) * s * (6 - s) + bx * s * s) / 36;
                    int256 y1 = (ay * (6 - s) * (6 - s) + 2 * sag * s * (6 - s) + by * s * s) / 36;
                    Raster.line(p, px0, py0, x1, y1, BRIDGE * 16 + fog / 2);
                    px0 = x1;
                    py0 = y1;
                }
            }
        }
    }

    function _windows(uint256 p, Building memory b, int256 dz, uint256 wfog) internal pure {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            uint256 lit = b.lit;
            uint256 warm = b.warm;
            int256 x0 = b.x0;
            int256 top = b.top;
            uint256 cw = WARM * 16 + wfog;
            uint256 cc = COOL * 16 + wfog;
            uint256 tall = dz < 1500 ? 1 : 0;
            assembly ("memory-safe") {
                for { let q := 0 } lt(q, 5) { q := add(q, 1) } {
                    let z := add(dz, sdiv(mul(add(mul(q, 10), 3), DEPTH), 50))
                    let wx := sar(4, add(VX16, sdiv(mul(x0, F16), z)))
                    if lt(wx, 128) {
                        let k := q
                        for { let r := 0 } lt(r, 30) { r := add(r, 1) } {
                            if and(shr(k, lit), 1) {
                                let y := add(top, sdiv(mul(add(shl(1, r), 1), sub(STREET, top)), 60))
                                let wy := sar(4, add(VY16, sdiv(mul(y, F16), z)))
                                if lt(wy, 127) {
                                    let c := cc
                                    if and(shr(k, warm), 1) { c := cw }
                                    let a := add(add(p, shl(7, wy)), wx)
                                    mstore8(a, c)
                                    if tall { mstore8(add(a, 128), c) }
                                }
                            }
                            k := add(k, 5)
                        }
                    }
                }
            }
        }
    }

    /// @dev The block's vertical neon sign hanging into the canyon. Close signs draw their glyphs; far ones are a glow.
    function _sign(uint256 p, bytes memory e, Building memory b, uint256 i, int256 dz, uint256 fog, uint256 f)
        internal
        pure
    {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            // Flicker: off for a moment in some signs, from the hash.
            if (
                ((f * 7 * 256 + e.hashByte(i, 6) * FRAMES) % (FRAMES * 256)) * 100
                    < 4 * (e.hashByte(i, 7) % 3) * FRAMES * 256
            ) {
                return;
            }
            int256 z = dz + 80;
            int256 px = _px(b.x0 - b.side * 220, z) >> 4;
            int256 py = _py(-1600 + int256(e.hashByte(i, 4)) * 800 / 255, z) >> 4;
            int256 fs = 15600 / z; // glyph size in px (0.3 units)
            if (fs < 1) fs = 1;
            SceneKit.verticalSign(p, b.word, px, py, fs, NEON + b.neon, fog * 7 / 10);
        }
    }

    /// @dev Flying traffic: streaks along the canyon at several heights; more with fuller blocks.
    function _traffic(uint256 p, bytes memory e, uint256 f) internal pure {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            uint256 cur = (f / 9 + 4) % 10;
            uint256 count = 10 + e.gasBps(cur) / 250;
            for (uint256 k; k < count; ++k) {
                uint256 b = k % 10;
                int256 lane = (int256(e.hashByte(b, k)) - 128) * 1600 / 255;
                int256 alt = -2200 + int256(e.hashByte(b, k + 5)) * 2600 / 255;
                int256 dir = k % 3 == 0 ? -1 : int256(1);
                int256 z = _wrap(int256(e.hashByte(b, k + 9)) * FAR / 255 - dir * int256(f) * FAR / int256(FRAMES), FAR)
                    + NEAR;
                int256 z2 = z + 450 * dir;
                if (z2 < NEAR) z2 = NEAR;
                uint256 c = (dir > 0 ? NEON + 5 : WHITE) * 16 + _fog(z) * 7 / 10;
                Raster.line(p, _px(lane, z) >> 4, _py(alt, z) >> 4, _px(lane, z2) >> 4, _py(alt, z2) >> 4, c);
            }
        }
    }

    /// @dev Foreground: a rooftop ledge and a lone figure looking down the canyon, rim-lit by the haze.
    function _ledge(uint256 p, uint256 f) internal pure {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            Raster.quad(p, [int256(0), 1597, 860, 1761, 860, 2048, 0, 2048], DARK * 16);
            Raster.line(p, 0, 99, 53, 110, DARK * 16 + 9);
            int256 sway = (f % 45) < 22 ? int256(0) : int256(1);
            // Head, coat lifted by the wind, rim light down the right side.
            Raster.disc(p, 35, 93, 1, DARK * 16);
            Raster.quad(p, [int256(534), 1515, 590, 1515, 626 + sway * 16, 1710, 520 + sway * 16, 1710], DARK * 16);
            Raster.line(p, 36, 92, 37, 95, DARK * 16 + 8);
            Raster.line(p, 37, 95, 39 + sway, 106, DARK * 16 + 8);
        }
    }
}

src/blockart/scenes/Descent.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {Raster} from "../Raster.sol";
import {Epoch} from "../Epoch.sol";
import {Glyphs} from "../Glyphs.sol";
import {SceneBase, SceneKit} from "../SceneBase.sol";

/// @notice 地下 DESCENT: riding the front of a train down a deep subway tunnel. Each block is a tunnel segment: wall
///         lamps lit from its logs bloom, a lit sign with its word and number, a signal at its start; the track runs
///         underneath toward the glow at the end of the line. Level camera, no rotation.
/// @dev Port of concepts/neo-tokyo/descent.js. Milli-units; camera 1.05 above the track, 16 units per loop.
contract Descent is SceneBase {
    using Epoch for bytes;

    int256 private constant SP = 1600;
    int256 private constant L = 16000;
    int256 private constant FAR = 15200;
    int256 private constant W = 1700;
    int256 private constant CAM_Y = -1050;
    int256 private constant F16 = 1024; // focal 64 px
    int256 private constant C16 = 1024; // centre 64 px

    uint256 private constant WALL = 1;
    uint256 private constant ROOF = 2;
    uint256 private constant RIB = 3;
    uint256 private constant WALL_B = 4;
    uint256 private constant NEON = 5;
    uint256 private constant FLOOR = 11;
    uint256 private constant LAMP = 12;
    uint256 private constant WHITE = 13;
    uint256 private constant SLEEPER = 14;
    uint256 private constant DARK = 15;

    function _palette(bytes memory) internal pure override returns (bytes memory) {
        return SceneKit.palette(
            [
                uint24(0),
                0x1a1426,
                0x14101e,
                0x2e2440,
                0x1f182e,
                0,
                0,
                0,
                0,
                0,
                0,
                0x0e0b14,
                0xffc878,
                0,
                0x2c2228,
                0x06040a
            ],
            0x280c38,
            0x785a46, // dark ramp ends at the third rail's rust
            hex"06030c0c041311061b1708221d0929220a31280c3844134d5f1a627a217796288cb93996dc49a0ff5aaaff8cc3ffbedc",
            ""
        );
    }

    /// @dev Darkness with the glow at the far end of the line, then everything that looks the same in every frame
    ///      (the camera only moves forward through a uniform tunnel): shell, rails and cable runs.
    function _backdrop(uint256 p, bytes memory e) internal pure override {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            SceneKit.sky(p, 16, 16, 64, 16, 64, 64, 58, 15);
            (int256[13] memory xs, int256[13] memory ys) = _profile();
            for (int256 dz = L - SP; dz >= 0; dz -= SP) {
                _shell_(p, e, 0, dz, xs, ys);
            }
            _rails(p, 5);
        }
    }

    function _profile() internal pure returns (int256[13] memory xs, int256[13] memory ys) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            xs = [int256(-1700), -1700, -1617, -1375, -999, -525, 0, 525, 999, 1375, 1617, 1700, 1700];
            ys = [int256(0), -1500, -1809, -2088, -2309, -2451, -2500, -2451, -2309, -2088, -1809, -1500, 0];
        }
    }

    function _sx(int256 x, int256 dz) internal pure returns (int256) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            return C16 + x * F16 / dz;
        }
    }

    function _sy(int256 y, int256 dz) internal pure returns (int256) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            return C16 + (y - CAM_Y) * F16 / dz;
        }
    }

    function _fogAt(int256 dz) internal pure returns (uint256) {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            return SceneKit.fog(dz, 0, FAR);
        }
    }

    function _draw(uint256 p, bytes memory e, uint256[] memory, uint256 f) internal pure override {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            int256 camZ = int256(f % SceneKit.FRAMES) * L / int256(SceneKit.FRAMES);
            (int256[13] memory xs, int256[13] memory ys) = _profile();
            // Segments far to near: one per block.
            int256[10] memory dzs;
            uint256[10] memory order;
            for (uint256 i; i < 10; ++i) {
                int256 dz = SceneKit.wrap(int256(i) * SP - camZ, L);
                uint256 j = i;
                while (j > 0 && dzs[j - 1] < dz) {
                    dzs[j] = dzs[j - 1];
                    order[j] = order[j - 1];
                    --j;
                }
                dzs[j] = dz;
                order[j] = i;
            }
            _ribs_(p, camZ, xs, ys);
            _track_(p, camZ);
            _rails(p, 3);
            // A ring lit in each block's colour where its segment begins.
            for (uint256 k; k < 10; ++k) {
                if (dzs[k] < 200 || dzs[k] > FAR) continue;
                uint256 c = (NEON + e.neon(order[k])) * 16 + _fogAt(dzs[k]) * 7 / 10;
                int256 px = _sx(xs[0], dzs[k]) >> 4;
                int256 py = _sy(ys[0], dzs[k]) >> 4;
                for (uint256 j = 1; j < 13; ++j) {
                    int256 qx = _sx(xs[j], dzs[k]) >> 4;
                    int256 qy = _sy(ys[j], dzs[k]) >> 4;
                    Raster.line(p, px, py, qx, qy, c);
                    px = qx;
                    py = qy;
                }
            }
            for (uint256 k; k < 10; ++k) {
                _fixtures_(p, e, order[k], dzs[k]);
            }
            SceneKit.hologram(p, e, SceneKit.turn(f, 100), 64, 3);
        }
    }

    /// @dev The tunnel shell of one segment: walls, arched roof and floor, shaded per block.
    function _shell_(uint256 p, bytes memory e, uint256 i, int256 dz, int256[13] memory xs, int256[13] memory ys)
        internal
        pure
    {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            int256 z0 = dz < 150 ? int256(150) : dz;
            int256 z1 = dz + SP;
            uint256 fog = _fogAt(dz);
            uint256 wall = WALL * 16 + fog;
            for (uint256 k; k < 12; ++k) {
                uint256 c = (ys[k] < -1500 || ys[k + 1] < -1500) ? ROOF * 16 + fog : wall;
                Raster.quad(
                    p,
                    [
                        _sx(xs[k], z1),
                        _sy(ys[k], z1),
                        _sx(xs[k + 1], z1),
                        _sy(ys[k + 1], z1),
                        _sx(xs[k + 1], z0),
                        _sy(ys[k + 1], z0),
                        _sx(xs[k], z0),
                        _sy(ys[k], z0)
                    ],
                    c
                );
            }
            Raster.quad(
                p,
                [_sx(-W, z1), _sy(0, z1), _sx(W, z1), _sy(0, z1), _sx(W, z0), _sy(0, z0), _sx(-W, z0), _sy(0, z0)],
                FLOOR * 16 + fog
            );
        }
    }

    /// @dev Ribs every 0.8 units: the arch outline, fogged with distance.
    function _ribs_(uint256 p, int256 camZ, int256[13] memory xs, int256[13] memory ys) internal pure {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            for (int256 z = (camZ / 800 + 1) * 800; z < camZ + FAR; z += 800) {
                int256 dz = z - camZ;
                if (dz < 200) continue;
                uint256 c = RIB * 16 + _fogAt(dz);
                int256 px = _sx(xs[0], dz) >> 4;
                int256 py = _sy(ys[0], dz) >> 4;
                for (uint256 k = 1; k < 13; ++k) {
                    int256 qx = _sx(xs[k], dz) >> 4;
                    int256 qy = _sy(ys[k], dz) >> 4;
                    Raster.line(p, px, py, qx, qy, c);
                    px = qx;
                    py = qy;
                }
            }
        }
    }

    /// @dev Fifty sleepers per 16-unit loop: spacing divides L so the seam preserves their phase.
    function _track_(uint256 p, int256 camZ) internal pure {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            for (int256 z = (camZ / 320 + 1) * 320; z < camZ + FAR; z += 320) {
                int256 dz = z - camZ;
                if (dz < 150) continue;
                Raster.quad(
                    p,
                    [
                        _sx(-550, dz),
                        _sy(0, dz),
                        _sx(550, dz),
                        _sy(0, dz),
                        _sx(550, dz + 100),
                        _sy(0, dz + 100),
                        _sx(-550, dz + 100),
                        _sy(0, dz + 100)
                    ],
                    SLEEPER * 16 + _fogAt(dz)
                );
            }
        }
    }

    /// @dev Two running rails, the third rail and a cable run on each wall, to the end of the line.
    function _rails(uint256 p, uint256 count) internal pure {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            int256[5] memory rx = [int256(-360), 360, 900, -W + 20, W - 20];
            int256[5] memory ry = [int256(-40), -40, -40, -1150, -1150];
            for (uint256 r; r < count; ++r) {
                // Start where the line enters the frame: |x| or |y - camera height| in front of the camera.
                int256 dz = rx[r] < 0 ? -rx[r] : rx[r];
                int256 dy = ry[r] - CAM_Y < 0 ? CAM_Y - ry[r] : ry[r] - CAM_Y;
                if (dy > dz) dz = dy;
                int256 px = _sx(rx[r], dz) >> 4;
                int256 py = _sy(ry[r], dz) >> 4;
                while (dz < FAR) {
                    dz = dz * 112 / 100 + 20;
                    if (dz > FAR) dz = FAR;
                    int256 qx = _sx(rx[r], dz) >> 4;
                    int256 qy = _sy(ry[r], dz) >> 4;
                    uint256 fog = _fogAt(dz);
                    uint256 c = r < 2 ? WHITE * 16 + fog * 7 / 10 : r == 2 ? DARK * 16 + 15 - fog / 3 : DARK * 16 + 1;
                    Raster.line(p, px, py, qx, qy, c);
                    px = qx;
                    py = qy;
                }
            }
        }
    }

    /// @dev Per block: wall lamps from the bloom, a signal at the segment start, and the lit sign mid-segment.
    function _fixtures_(uint256 p, bytes memory e, uint256 i, int256 dz) internal pure {
        unchecked { // Frame, hash and geometry bounds are documented in SceneBase/scene constants.

            uint256 fog = _fogAt(dz);
            for (uint256 k; k < 16; ++k) {
                if (!e.bloomBit(i, k * 7 + i) || !e.hashBit(i, k)) continue;
                int256 side = k % 2 == 1 ? int256(1) : -1;
                int256 z = dz + (int256(k / 2) * 2 + 1) * SP / 16;
                if (z < 200) continue;
                int256 x = _sx(side * (W - 30), z) >> 4;
                int256 y = _sy(-1350, z) >> 4;
                uint256 c = (e.stateByte(i, k) & 1 == 1 ? LAMP : NEON + 1) * 16 + fog * 7 / 10;
                int256 s = 50000 / z / 16;
                Raster.rect(p, x - s, y, x + s + 1, y + s / 2 + 1, c);
            }
            // Signal: green ahead, red once it is near.
            if (dz > 200) {
                int256 x = _sx(-W + 150, dz + 50) >> 4;
                int256 y = _sy(-1000, dz + 50) >> 4;
                int256 r = 2400 / (dz + 50);
                Raster.disc(p, x, y, r, (dz < SP * 3 / 2 ? NEON + 5 : NEON + 4) * 16 + fog * 6 / 10);
            }
            // The block's sign on the wall: the word vertically, its number below when close.
            int256 zs = dz + SP / 2;
            if (zs > 300) {
                int256 side = e.hashByte(i, 0) & 1 == 1 ? int256(1) : -1;
                int256 fs = 9600 / zs;
                if (fs < 1) fs = 1;
                int256 x = (_sx(side * (W - 50), zs) >> 4) - side * fs * 6 / 10;
                int256 y = _sy(-1750, zs) >> 4;
                SceneKit.verticalSign(p, e.word(i), x, y, fs, NEON + e.neon(i), _fogAt(zs) * 6 / 10);
                if (fs >= 8) {
                    (uint256 len,) = Glyphs.word(e.word(i));
                    Raster.number(p, x, y + fs * int256(len * 108 + 70) / 100, e.number(i), (NEON + e.neon(i)) * 16);
                }
            }
        }
    }
}

