// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {SolVideo} from "../src/SolVideo.sol";
import {MpegVideo} from "../src/MpegVideo.sol";
import {Scene} from "../src/Scene.sol";
import {Vm} from "./SolVideo.t.sol";

contract BallsFrameHarness is Scene {
    function frame(uint256 size, uint256 f, uint256 frames, uint256 scene, uint256 seed)
        external
        pure
        returns (bytes memory pixels, bytes memory palette)
    {
        pixels = new bytes(size * size);
        _draw(pixels, size, f, frames, scene, seed);
        palette = _palette(scene, seed);
    }
}

contract GhoulBallsTest {
    Vm constant vm = Vm(address(uint160(uint256(keccak256("hevm cheat code")))));

    event log_named_uint(string key, uint256 val);
    event log(string val);

    function _export(address renderer, bytes memory input, string memory name, string memory extension) private {
        uint256 beforeGas = gasleft();
        (bool ok, bytes memory result) = renderer.staticcall{gas: 500_000_000}(input);
        uint256 used = beforeGas - gasleft();
        require(ok, "Ghoul Balls preset exceeds budget or reverts");
        bytes memory media = abi.decode(result, (bytes));
        emit log(name);
        emit log_named_uint("gas including STATICCALL and return copy", used);
        emit log_named_uint("file bytes", media.length);
        vm.writeFileBinary(string.concat("previews/", name, extension), media);
        vm.writeFile(
            string.concat("previews/", name, ".json"),
            string.concat(
                "{\"success\":true,\"seed\":42,\"gas\":",
                vm.toString(used),
                ",\"bytes\":",
                vm.toString(media.length),
                "}"
            )
        );
    }

    function _all(uint256 scene) private {
        SolVideo lossless = new SolVideo();
        MpegVideo mpeg = new MpegVideo();
        string memory suffix = string.concat("-25-", vm.toString(scene));
        _export(
            address(lossless),
            abi.encodeCall(lossless.avi, (64, 25, scene, 42)),
            string.concat("avi-64", suffix),
            ".avi"
        );
        _export(
            address(lossless),
            abi.encodeCall(lossless.gif, (64, 25, scene, 42)),
            string.concat("gif-64", suffix),
            ".gif"
        );
        _export(address(mpeg), abi.encodeCall(mpeg.mpeg, (512, scene, 42)), string.concat("mpeg-512", suffix), ".m1v");
        _export(address(mpeg), abi.encodeCall(mpeg.mpg, (512, scene, 42)), string.concat("mpg-512", suffix), ".mpg");
    }

    function testOneBall() public {
        _all(3);
    }

    function testTwoBalls() public {
        _all(4);
    }

    function testFourBalls() public {
        _all(5);
    }

    function testSixBalls() public {
        _all(6);
    }

    function testSixBalls128Lossless() public {
        SolVideo lossless = new SolVideo();
        _export(address(lossless), abi.encodeCall(lossless.avi, (128, 25, 6, 42)), "avi-128-25-6", ".avi");
        _export(address(lossless), abi.encodeCall(lossless.gif, (128, 25, 6, 42)), "gif-128-25-6", ".gif");
    }

    function testFramePeriodAndSeed() public {
        BallsFrameHarness harness = new BallsFrameHarness();
        for (uint256 scene = 3; scene <= 6; ++scene) {
            (bytes memory first, bytes memory palette) = harness.frame(64, 0, 50, scene, 42);
            (bytes memory looped,) = harness.frame(64, 50, 50, scene, 42);
            (bytes memory changed, bytes memory changedPalette) = harness.frame(64, 0, 50, scene, 43);
            require(keccak256(first) == keccak256(looped), "Loop endpoint differs");
            require(keccak256(first) != keccak256(changed), "Seed does not affect positions");
            require(keccak256(palette) != keccak256(changedPalette), "Seed does not affect colours");
            require(palette[0] == 0 && palette[1] == 0 && palette[2] == 0, "Background is not black");
            for (uint256 i; i < first.length; ++i) {
                require(uint8(first[i]) <= 6, "Invalid ball index");
            }
        }
    }
}

test/MarketplaceProbe.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import {MarketplaceProbe} from "../src/probes/MarketplaceProbe.sol";
import {Vm} from "./SolVideo.t.sol";

interface VmProbe is Vm {
    function readFileBinary(string calldata path) external view returns (bytes memory);
    function expectRevert(bytes calldata data) external;
    function envOr(string calldata name, string calldata defaultValue) external view returns (string memory);
    function envOr(string calldata name, bool defaultValue) external view returns (bool);
}

contract MarketplaceProbeTest {
    VmProbe constant vm = VmProbe(address(uint160(uint256(keccak256("hevm cheat code")))));
    address constant RECIPIENT = address(uint160(0xA11CE));
    MarketplaceProbe probe;
    bytes32 expectedHash;
    event log_named_uint(string name, uint256 value);

    function setUp() public {
        bytes memory source = vm.readFileBinary("fixtures/marketplace-probe/large-html.uri");
        expectedHash = keccak256(source);
        probe = MarketplaceProbe(payable(VmContractHelper73(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D).deployCode({_artifact: "src/probes/MarketplaceProbe.sol:MarketplaceProbe", _args: encodeArgs54(DeployHelper54.FoundryPpConstructorArgs(RECIPIENT, "https://ghoulballs.vercel.app/probe/player.html"))})));
    }

    function testFixedSupplyAndPayloadIntegrity() public view {
        require(probe.totalSupply() == 15 && probe.balanceOf(RECIPIENT) == 15, "Wrong probe set");
        for (uint256 id = 1; id <= 15; ++id) {
            require(probe.ownerOf(id) == RECIPIENT, "Wrong recipient");
        }
        require(probe.largeURIHash() == expectedHash, "Wrong payload hash");
        require(keccak256(bytes(probe.tokenURI(11))) == expectedHash, "Stored payload changed");
        require(address(probe).code.length <= 24576, "Probe runtime exceeds Base code limit");
    }

    /// @dev Exports to previews/probe/ only with PROBE_EXPORT=true, so a normal `forge test` leaves the tree clean.
    function testAllMetadataWithin500MAndExport() public {
        bool exporting = vm.envOr("PROBE_EXPORT", false);
        string memory records = "[";
        for (uint256 id = 1; id <= 15; ++id) {
            uint256 beforeGas = gasleft();
            (bool ok, bytes memory result) =
                address(probe).staticcall{gas: 500000000}(abi.encodeCall(probe.tokenURI, (id)));
            uint256 used = beforeGas - gasleft();
            require(ok, "Probe metadata failed below 500M");
            string memory uri = abi.decode(result, (string));
            uint256 target = probe.gasTarget(id);
            if (target != 0) require(used >= target && used < target + 2000000, "Gas ladder not calibrated");
            else require(used < 40000000, "Non-gas control is not cheap");
            emit log_named_uint(probe.caseName(id), used);
            if (exporting) vm.writeFile(string.concat("previews/probe/token-", vm.toString(id), ".uri.txt"), uri);
            records = string.concat(
                records,
                id == 1 ? "" : ",",
                '{"token_id":',
                vm.toString(id),
                ',"name":"',
                probe.caseName(id),
                '","gas":',
                vm.toString(used),
                ',"target_gas":',
                vm.toString(target),
                ',"uri_bytes":',
                vm.toString(bytes(uri).length),
                "}"
            );
        }
        if (!exporting) return;
        string memory profile = vm.envOr("FOUNDRY_PROFILE", string("default"));
        bool isBase =
            keccak256(bytes(profile)) == keccak256("base") || keccak256(bytes(profile)) == keccak256("base_sepolia");
        vm.writeFile(
            isBase ? "previews/probe/measurements.base.json" : "previews/probe/measurements.amsterdam.json",
            string.concat(records, "]")
        );
    }

    function testFiftyMillionReadSeparatesGasLadder() public view {
        for (uint256 id = 1; id <= 7; ++id) {
            (bool ok,) = address(probe).staticcall{gas: 50000000}(abi.encodeCall(probe.tokenURI, (id)));
            require(ok == (id <= 3), "50M boundary does not isolate gas");
        }
    }

    function testNonexistentURIReverts() public {
        vm.expectRevert(abi.encodeWithSignature("ERC721NonexistentToken(uint256)", uint256(16)));
        probe.tokenURI(16);
    }

    function testRejectsZeroRecipient() public {
        vm.expectRevert(abi.encodeWithSignature("ERC721InvalidReceiver(address)", address(uint160(0))));
        MarketplaceProbe(payable(VmContractHelper73(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D).deployCode({_artifact: "src/probes/MarketplaceProbe.sol:MarketplaceProbe", _args: encodeArgs54(DeployHelper54.FoundryPpConstructorArgs(address(uint160(0)), "https://ghoulballs.vercel.app/probe/player.html"))})));
    }

    function testRejectsInsecureHostedURL() public {
        vm.expectRevert(abi.encodeWithSelector(MarketplaceProbe.InvalidHostedURL.selector));
        MarketplaceProbe(payable(VmContractHelper73(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D).deployCode({_artifact: "src/probes/MarketplaceProbe.sol:MarketplaceProbe", _args: encodeArgs54(DeployHelper54.FoundryPpConstructorArgs(RECIPIENT, "http://example.com"))})));
    }
}

import {DeployHelper54, encodeArgs54} from "foundry-pp/DeployHelper54.sol";

interface VmContractHelper73 {
    function deployCode(string memory _artifact) external returns (address);
    function deployCode(string memory _artifact, bytes32 _salt) external returns (address);
    function deployCode(string memory _artifact, bytes memory _args) external returns (address);
