contract ReenterEpoch {
    bool public blocked;

    function mint(BlockArtNFT nft, bytes[] memory headers) external {
        nft.mint(5254696, headers);
    }

    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        try BlockArtNFT(msg.sender).mint(5254696, BaseEpochs.epoch5254696()) {
            revert("Reentry succeeded");
        } catch (bytes memory reason) {
            require(bytes4(reason) == BlockArtNFT.AlreadyMinted.selector, "Unexpected reentry failure");
            blocked = true;
        }
        return this.onERC721Received.selector;
    }
}

contract EpochRulesTest {
    using Epoch for bytes;
    RulesVm constant vm = RulesVm(address(uint160(uint256(keccak256("hevm cheat code")))));
    BlockArtNFT nft;
    BlockArtRenderer renderer;

    function setUp() public {
        address[8] memory scenes;
        for (uint256 i; i < 8; ++i) {
            scenes[i] = address(new UnusedScene());
        }
        renderer = BlockArtRenderer(payable(VmContractHelper94(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D).deployCode({_artifact: "src/blockart/BlockArtRenderer.sol:BlockArtRenderer", _args: encodeArgs31(DeployHelper31.FoundryPpConstructorArgs(scenes))})));
        nft = BlockArtNFT(payable(VmContractHelper94(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D).deployCode({_artifact: "src/blockart/BlockArtNFT.sol:BlockArtNFT", _args: encodeArgs33(DeployHelper33.FoundryPpConstructorArgs(renderer))})));
